/**
 * ISMS register catalogue (ISO/IEC 27001:2022 clauses 4–10).
 *
 * Every register that is not backed by an existing module (assets, access, incidents, threat intel,
 * controls …) is stored as an IsmsRecord and described here. The column labels are copied from the
 * spreadsheets in the Global SJX ISO-27001 client folder, so a generated file has the same headings
 * as the one the team already uses and an old file can be imported again by heading.
 */
export type ColType = 'text' | 'longtext' | 'date' | 'select' | 'number' | 'yn' | 'url';
export interface Col {
  key: string;
  label: string;
  type?: ColType;
  options?: string[];
  /** other headings seen in the company spreadsheets (used when importing) */
  aliases?: string[];
  /** calculated by the server, never typed */
  computed?: boolean;
  /** shown as a column in the table (the rest appear in the form / export only) */
  list?: boolean;
}
export interface RegisterDef {
  key: string;
  title: string;
  docId: string;
  clause: string;
  group: 'Context & leadership' | 'Planning' | 'Support' | 'Operation' | 'Performance' | 'Improvement';
  description: string;
  prefix: string;
  statuses: string[];
  closedStatuses: string[];
  defaultStatus: string;
  titleKey: string;
  /** record data key holding the due date used by reminders */
  dueKey?: string;
  cols: Col[];
  /** sheet names (regex source) used when importing a workbook */
  sheetMatch: string[];
  /** which policy / procedure this register evidences */
  policy: string;
}

const YN = ['Yes', 'No'];
const L5 = ['1', '2', '3', '4', '5'];
const FREQ = ['One-off', 'Weekly', 'Monthly', 'Quarterly', 'Bi-annual', 'Annual'];
